for (const [id, lines] of Object.entries(TM_MORE)) {
    if (!TALK_MORE[id]) TALK_MORE[id] = [];
    TALK_MORE[id].push(...lines);
}

/* ---------------------------------------------------------------- helpers */
/* a topic never breaks a conversation: a problem (an old save without a field, say) just means nothing to say */
function tmSafe(fn, none) { return n => { try { return fn(n); } catch (e) { console.error('talk topic:', e); return none; } }; }
function tmPick(v) { return Array.isArray(v) ? rpick(v) : v || null; }
function tmFill(line, vars) { return line ? String(line).replace(/\{(\w+)\}/g, (m, k) => (vars[k] != null ? String(vars[k]) : m)) : line; }
function tmHourKey() { const h = Clock.hourF(); return h >= 4 && h < 8 ? 'dawn' : h >= 8 && h < 12 ? 'morning' : h >= 12 && h < 17 ? 'afternoon' : h >= 17 && h < 21 ? 'evening' : 'late'; }
function tmName(id) { return (NPC_DEFS[id] && NPC_DEFS[id].name) || id; }
const TM_PEOPLE = new Set(NEIGHBORS.concat(['joe']));
/* whoever else is around (in a room: everyone in it; outside: within ten tiles) */
function tmNearby(n) {
    if (!n || !G.area || typeof NPCs === 'undefined') return [];
    const out = [];
    for (const o of NPCs.here()) {
        if (o === n || o.sleeping || !TM_PEOPLE.has(o.id)) continue;
        if (n.area === 'island' && Math.hypot(o.x - n.x, o.y - n.y) > 10 * TILE) continue;
        out.push(o);
    }
    return out;
}
/* where someone is standing, most particular first: their own house, their work, a room, then the spot outside */
const TM_SPOT_MORE = { goatpen: 'farm', oldtree: 'forest', summit: 'lookout', lighthousefront: 'lighthouse', eastmeadow: 'meadow', jog: 'orchard',
    beach_e: 'beach', beach_w: 'beach', beach_far: 'beach', bench_lookout: 'lookout', bench_falls: 'waterfall', bench_pond: 'pond', bench_museum: 'museumfront' };
function tmPlaceKeys(n) {
    const id = n.id, a = n.area || '', k = String(n.spotKey || '');
    if (a && a !== 'island') {
        if (a === 'h_' + id) return ['myhome'];
        if (ROOMS[a] && ROOMS[a].staff === id) return ['work', a];
        if (a === 'home') return ['sarahs'];
        return [a === 'lamproom' ? 'lighthouse' : a];
    }
    if (k === 'home') return ['doorstep'];
    if (k.startsWith('party:')) return ['party', k.slice(6)];
    if (k.startsWith('picnic_')) return ['picnic', 'forest'];
    const g = typeof placeGroup === 'function' ? placeGroup(k) : k;
    return [k, g, TM_SPOT_MORE[k], TM_SPOT_MORE[g]].filter(Boolean);
}

