const TM_SEASON = {
    maki: { spring: 'Cherry blossom season. Petals land wherever they want. I am learning to let them. It is very hard.', summer: 'Summer makes rice sticky. And people. Everyone stays outside too long and says yes to too many things.',
        fall: 'Leaves fall in no particular order. I rake them into order. The wind disagrees. We are in a dialogue.', winter: 'In winter I wear a scarf, wrapped exactly twice. Three times is excessive. Once is a statement I am not ready to make.' },
    kai: { spring: "Spring, dude! The fish are all waking up like, 'what'd we miss?' Everything, fish. You missed everything.", summer: "Summer's my season, bro. Warm water, long days, sunburn on one ear. Life is a bowl.",
        fall: "Fall's chill. The beach is empty. Just me and the crabs. The crabs have gotten very comfortable.", winter: "Winter fishing is the best-kept secret, dude. The fish are slow, I'm slow, we're all slow together." },
    basil: { spring: "Spring is when I plant the basil. It's like planting a tiny me. I water it and tell it to stay calm.", summer: "In summer the cart is busy until one. Everyone's out late. Everyone's hungry. My favorite season, honestly.",
        fall: 'Fall is for curry. The air gets cool and everyone wants something warm and a little spicy. A hug with chili in it.', winter: "In winter people hold their bowls with both hands. That's the best compliment a noodle cart can get." },
    wonton: { spring: "Flowers float into the spring sometimes. I wear them like a little hat. People say I look like a garnish. I'm choosing to hear 'hat.'", summer: "In summer people say the spring is 'too hot.' It's the same temperature every day! It's the WORLD that's too hot.",
        fall: "Fall leaves float in the spring. Very pretty. Then somebody says it looks like tea. Tea is soup's cousin. I don't like it.", winter: 'Winter evenings, the spring is the warmest place on the island. Everyone comes. Even Maki. He stays exactly ten minutes.' },
    chili: { spring: "Spring. My pepper garden's growing. Little baby peppers. So small. So furious. I love them.", summer: "Summer and me? Basically the same thing. People keep asking if I'm the reason it's so hot. I'm not saying no.",
        fall: "Fall's when the peppers turn red. Everybody says they look like me. I say I look like them. We're very close.", winter: "Winter's fine. I'm the island's space heater. People stand next to me and go 'ahh.'" },
    coco: { spring: "Spring is crush season, girl. Everybody's acting weird and blushing at each other. And I'm watching. I'm always watching.", summer: 'Summer is hard on a truffle. I stay inside till four, then I am everywhere. Summer evenings are prime gossip hours.',
        fall: "Fall is cozy season. Sweaters, cocoa, and everybody inside telling secrets. It's my Super Bowl.", winter: "Winter is perfect. I don't melt, there's cocoa everywhere, and everyone's indoors with nothing to do but talk." },
    cece: { spring: "Spring makes me so happy. Strawberries, cherries, little flowers. I bake something pink every day. Sorry. It's a lot of pink.", summer: 'Summer is scary for a cheesecake. I keep a little fan pointed at me. And another one pointed at the fan. Just in case.',
        fall: "It's pumpkin cheesecake season! I've already made six. I'm saving them. For what? I don't know! Sorry!", winter: 'In winter I bake all day to keep my house warm. My house is very warm. My neighbors are very full.' },
    clementine: { spring: 'Spring is pastel. I tolerate pastel. I tolerate it in orange.', summer: 'Summer is linen and big hats. I wear the biggest hat. People find me by the shade.',
        fall: "It's fall. My season. Every tree on the island is finally dressed correctly.", winter: "Winter is for long coats. The kind that make you look like you're leaving a party early, on purpose." },
    cuke: { spring: "Spring! The days are getting longer! More daylight means more jogging! I've never been more ready!", summer: 'Summer! The sun comes up at 5, so I get a whole hour of jogging in the dark first! Bonus jog!',
        fall: 'Fall! Crunchy leaves are like a running track that claps for you! Crunch crunch crunch!', winter: "Winter sunrise is SO late! I've been up three hours before it shows up! I wait for it like an old friend!" },
    sully: { spring: 'Spring, kid. Back home that means mud season, then pothole season, then two good weeks. Here it just means flowers. Spoiled.', summer: "Summer back home meant the Cape. Four hours in traffic to sit on a beach for one. Worth it. Don't ask me why.",
        fall: "Fall in New England, kid. Leaves, cider, apple picking. You never seen color like it. Clementine went once. She cried.", winter: "Winter's when the studio's the warmest spot on the island. Kiln's running, radio's on. Everybody drops by 'just to look.' They come to warm their hands." },
    ginger: { spring: "Spring is fixing season. Everything the winter loosened, I tighten. I'm the island's spring cleaning.", summer: "Summer's hard on gingerbread. I work early and late, and in the middle I sit in the shade and think about porches.",
        fall: "Fall's for roofs. Get them ready before the rain. Also for pumpkin bread. Mostly for pumpkin bread.", winter: "Snow on a gingerbread roof is the prettiest thing in the world. It's also icing, technically. Very sturdy icing." },
    brulee: { spring: 'Spring brings the biggest crowds to the museum. Everyone wants to look at flowers that cannot wilt. Paintings are very good at that.', summer: 'Summer is hard on a cr\u00e8me br\u00fbl\u00e9e. I keep the museum cool. For the art. Also for my top. Mostly my top.',
        fall: "Fall has the best colors. Every walk is a gallery. I keep stopping to say 'ah.' It takes me an hour to get to work.", winter: 'Winter light is so pale and gentle. Everyone looks like a sketch. I love sketches. They are honest.' },
    mac: { spring: 'Spring vegetables! Peas, carrots, little onions. Not green onions. Not near Wonton. Every other onion.', summer: "Summer means grilling. Corn, peppers, a whole lot of cheese on top. Chili says I grill wrong. Chili grills with his hands.",
        fall: "Fall is comfort food season. I'm comfort food. So it's my season. Every season's my season, really.", winter: "Winter is for long dinners. Nobody wants to leave the table. I don't blame them. The table's warm and I keep bringing bread." },
};
function tmWeatherLine(n) { const t = TM_WEATHER[n.id]; return t ? tmPick(t[G.weather]) : null; }
function tmSeasonLine(n) { const t = TM_SEASON[n.id]; return t ? tmPick(t[Clock.season()]) : null; }

