const TM_SHARE_AT = [70, 100];          // friendship points for four hearts, then five (HEARTS in 50_talk.js)
function tmShareDue(n) {
    const M = TM_SHARE[n.id], r = S.npcs && S.npcs[n.id];
    if (!M || !r) return false;
    const got = r.shared || 0;
    if (got >= M.length || (r.pts || 0) < TM_SHARE_AT[got]) return false;
    return r.sharedDay !== Clock.dayNum();     // one a day: the second one waits for another day
}
function tmShareLine(n) {
    if (!tmShareDue(n)) return null;
    const r = rel(n.id), got = r.shared || 0;
    r.shared = got + 1; r.sharedDay = Clock.dayNum();
    Save.touch();
    return TM_SHARE[n.id][got].slice();
}

