const TM_TODAY_MIN = { ate: 2, gifts: 2, sold: 5, talks: 6 };
function tmTodayCount(k) { if (typeof today !== 'function') return 0; return k === 'flowers' ? today('flowers') + today('flower') : today(k); }
function tmTodayLines(n) {
    const c = [];
    for (const [k, t] of Object.entries(TM_TODAY)) {
        if (!t[n.id]) continue;
        const v = tmTodayCount(k);
        if (v >= (TM_TODAY_MIN[k] || 1)) c.push(tmFill(t[n.id], { n: fmtNum(v), n1: fmtNum(v + 1), fishword: plural(v, 'fish', 'fish'), gameword: plural(v, 'game') }));
    }
    return c;
}
function tmTodayLine(n) { const c = tmTodayLines(n); return c.length ? rpick(c) : null; }

/* ---------------------------------------------------------------- Sarah's records: fish, pottery, the museum, the arcade... */
function tmRecordLines(n) {
    const st = S.stats || {}, c = [], id = n.id;
    const fish = st.fish || 0, pots = Math.max((S.pottery && S.pottery.made) || 0, st.pottery || 0), gifts = st.donated || 0;
    if (id === 'kai' && fish >= 10) c.push(`You've caught ${fmtNum(fish)} fish since you got here, dude. That's like, a whole school. You could teach it.`);
    if (id === 'maki' && fish >= 10) c.push(`You have caught ${fmtNum(fish)} fish in total. Exactly ${fmtNum(fish)}. I keep count. Somebody has to.`);
    if (id === 'sully' && pots > 0) c.push(`You've made ${fmtNum(pots)} ${plural(pots, 'piece')} in my studio, kid. Every one's got a little bit of you in it. Don't get sentimental. Okay. A little.`);
    if (id === 'brulee' && gifts > 0) c.push(`You have given the museum ${fmtNum(gifts)} ${plural(gifts, 'piece')}. Each one has its own little card. I write the cards myself, with my best pen.`);
    if (id === 'chili' && S.arcade && S.arcade.best) {
        const games = Object.keys(S.arcade.best).filter(g => S.arcade.best[g] > 0 && ARCADE_GAMES[g]);
        if (games.length) { const g = rpick(games); c.push(`Your best at ${ARCADE_GAMES[g].name} is ${fmtNum(S.arcade.best[g])}. I have it on a sticky note. On my fridge. It mocks me.`); }
    }
    const rope = (S.rope && S.rope.best) || 0;
    if (id === 'cuke' && rope > 0) c.push(`Your jump rope record is ${fmtNum(rope)}! That's so good! Mine is, um, I lost count! I always lose count!`);
    const golds = Object.values(S.cookLog || {}).filter(x => x && x.medal === 'gold').length;
    if (id === 'mac' && golds > 0) c.push(`You've got ${fmtNum(golds)} gold ${plural(golds, 'medal')} in cooking? Come work in my kitchen. Kidding. Unless? No. Unless?`);
    if (id === 'basil' && (st.cooked || 0) >= 5) c.push(`You've cooked ${fmtNum(st.cooked)} dishes since you got here. Your kitchen must smell like a good life.`);
    if (id === 'coco' && (st.talks || 0) >= 30) c.push(`You've had ${fmtNum(st.talks)} conversations on this island. I've been in about half of them. The good half.`);
    if (id === 'clementine' && (st.sewn || 0) > 0) c.push(`You've sewn ${fmtNum(st.sewn)} ${plural(st.sewn, 'outfit')}. I've noticed every stitch. Most of them were straight.`);
    if (id === 'ginger' && (st.wood || 0) >= 10) c.push(`You've chopped ${fmtNum(st.wood)} pieces of wood since you got here. That's a lot of porch. I'm just saying.`);
    if (id === 'wonton' && (st.clams || 0) > 0) c.push(`You've dug up ${fmtNum(st.clams)} ${plural(st.clams, 'clam')}. I'm not judging. They were just having a nice warm nap in the sand. Like me.`);
    return c;
}
function tmRecordLine(n) { const c = tmRecordLines(n); return c.length ? rpick(c) : null; }

