/* lines for today's holidays, and how often they come up: a one-day holiday a lot, a long stretch (Winter Lights) less */
function tmHolidays(n) {
    const id = n.id, c = [];
    let w = 0;
    for (const h of (typeof holidaysToday === 'function' ? holidaysToday() : [])) {
        if (!h || !h.id) continue;
        const k = c.length;
        if (h.npc === id) { if (TM_MY_DAY[id]) c.push(TM_MY_DAY[id]); }
        else {
            if (h.npc && TM_THEIR_DAY[h.npc]) c.push(...TM_THEIR_DAY[h.npc]);
            const t = TM_HOL[h.id];
            if (t && t[id]) c.push(t[id], t[id]);
            else if (t && t.any) c.push(t.any);
        }
        if (c.length > k) w = Math.max(w, (h.days || 1) > 3 ? 0.9 : 2.2);
    }
    return { lines: c, w };
}
function tmHolidayLine(n) { const c = tmHolidays(n).lines; return c.length ? rpick(c) : null; }

