function tmSolvedLines(n) {
    if (typeof Quests === 'undefined') return [];
    return Object.keys(TM_SOLVED).filter(q => TM_SOLVED[q][n.id] && Quests.done(q)).map(q => TM_SOLVED[q][n.id]);
}
function tmSolvedLine(n) { const c = tmSolvedLines(n); return c.length ? rpick(c) : null; }

